import re, json, math
txt=open('submission/model.ifc').read()
ents={}
for mm in re.finditer(r'#(\d+)=([A-Z0-9]+)\((.*?)\);\s*\n', txt, re.S):
    ents[int(mm.group(1))]=(mm.group(2),mm.group(3))

def split_args(a):
    out=[];depth=0;cur=''
    for ch in a:
        if ch=='(':
            depth+=1;cur+=ch
        elif ch==')':
            depth-=1;cur+=ch
        elif ch==',' and depth==0:
            out.append(cur);cur=''
        else:
            cur+=ch
    out.append(cur)
    return out
def refs(s): return [int(x) for x in re.findall(r'#(\d+)',s)]

agg={}
for i,(t,a) in ents.items():
    if t=='IFCRELAGGREGATES':
        args=split_args(a)
        parent=refs(args[4])[0]
        children=refs(args[5])
        agg.setdefault(parent,[]).extend(children)
sites=[i for i,(t,a) in ents.items() if t=='IFCSITE']
buildings=[i for i,(t,a) in ents.items() if t=='IFCBUILDING']
print('site',sites,'buildings',buildings)
site=sites[0]
print('site children',sorted(agg.get(site,[])))
for b in buildings:
    nm=split_args(ents[b][1])[2]
    print('building',b,nm,'storeys',agg.get(b))
