    print(nw['id'],nw['type'],'phase',nw.get('phase'),'width',nw.get('width_m'),'npts',len(nw['geom']))

# geometry helpers
def seglen(p,q): return math.hypot(q[0]-p[0],q[1]-p[1])
def plen(geom): return sum(seglen(geom[i],geom[i+1]) for i in range(len(geom)-1))
def pt_seg_dist(p,a,b):
    ax,ay=a;bx,by=b;px,py=p
    dx=bx-ax;dy=by-ay
    L2=dx*dx+dy*dy
    if L2==0: return math.hypot(px-ax,py-ay)
    t=max(0,min(1,((px-ax)*dx+(py-ay)*dy)/L2))
    return math.hypot(px-(ax+t*dx),py-(ay+t*dy))
def pl_dist(p,g): return min(pt_seg_dist(p,g[i],g[i+1]) for i in range(len(g)-1))
def poly_pl_dist(poly,g): return min(pl_dist(v,g) for v in poly)
def seg_seg_intersect(a,b,c,d):
    def ccw(p,q,r): return (r[1]-p[1])*(q[0]-p[0])-(q[1]-p[1])*(r[0]-p[0])
    d1=ccw(c,d,a);d2=ccw(c,d,b);d3=ccw(a,b,c);d4=ccw(a,b,d)
    if ((d1>0)!=(d2>0)) and ((d3>0)!=(d4>0)): return True
    return False
def seg_seg_dist(a,b,c,d):
    if seg_seg_intersect(a,b,c,d): return 0.0
    return min(pt_seg_dist(a,c,d),pt_seg_dist(b,c,d),pt_seg_dist(c,a,b),pt_seg_dist(d,a,b))
def poly_poly_dist(P,Q):
    best=1e9
    for i in range(len(P)):
        for j in range(len(Q)):
            best=min(best,seg_seg_dist(P[i],P[(i+1)%len(P)],Q[j],Q[(j+1)%len(Q)]))
    return best
def point_in_poly(p,poly):
    x,y=p;n=len(poly);inside=False
    j=n-1
    for i in range(n):
        xi,yi=poly[i];xj,yj=poly[j]
        if ((yi>y)!=(yj>y)) and (x < (xj-xi)*(y-yi)/(yj-yi)+xi): inside=not inside
        j=i
    return inside
def poly_area(poly):
    A=0
    for i in range(len(poly)):
        x1,y1=poly[i];x2,y2=poly[(i+1)%len(poly)]
        A+=x1*y2-x2*y1
    return abs(A)/2

