def ray_rect_block(P,Q,rect,h):
    px,py,pz=P;qx,qy,qz=Q;dx=qx-px;dy=qy-py;dz=qz-pz
    xs=[r[0] for r in rect];ys=[r[1] for r in rect]
    xmin,xmax=min(xs),max(xs);ymin,ymax=min(ys),max(ys)
    t0,t1=0.0,1.0
    for p,d,mn,mx in [(px,dx,xmin,xmax),(py,dy,ymin,ymax)]:
        if abs(d)<1e-12:
            if p<mn or p>mx:return False
        else:
            ta=(mn-p)/d;tb=(mx-p)/d
            if ta>tb:ta,tb=tb,ta
            t0=max(t0,ta);t1=min(t1,tb)
    if t0>t1:return False
    z0=pz+dz*t0;z1=pz+dz*t1
    return not(max(z0,z1)<0 or min(z0,z1)>h)
